import{_ as s,o as n,c as p,ag as t}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"实用主义哲学：效果导向的智慧","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/philosophy/pragmatism.md","filePath":"topics/philosophy/pragmatism.md"}'),e={name:"topics/philosophy/pragmatism.md"};function l(i,a,o,r,c,d){return n(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="实用主义哲学-效果导向的智慧" tabindex="-1">实用主义哲学：效果导向的智慧 <a class="header-anchor" href="#实用主义哲学-效果导向的智慧" aria-label="Permalink to &quot;实用主义哲学：效果导向的智慧&quot;">​</a></h1><blockquote><p>实用主义（Pragmatism）是美国本土产生的第一个哲学流派，强调<strong>思想的功能在于指导行动，真理的标准在于实际效果</strong>。它不仅影响了美国的社会制度，更与中国近现代史深度交织——胡适传播实用主义，毛泽东的实践论更直接吸收了实用主义的方法论精髓。</p><p>整理日期：2026-06-17</p></blockquote><hr><h2 id="一、实用主义的起源-皮尔斯的意义论" tabindex="-1">一、实用主义的起源：皮尔斯的意义论 <a class="header-anchor" href="#一、实用主义的起源-皮尔斯的意义论" aria-label="Permalink to &quot;一、实用主义的起源：皮尔斯的意义论&quot;">​</a></h2><h3 id="_1-1-查尔斯·桑德斯·皮尔斯-charles-sanders-peirce-1839-1914" tabindex="-1">1.1 查尔斯·桑德斯·皮尔斯（Charles Sanders Peirce, 1839-1914） <a class="header-anchor" href="#_1-1-查尔斯·桑德斯·皮尔斯-charles-sanders-peirce-1839-1914" aria-label="Permalink to &quot;1.1 查尔斯·桑德斯·皮尔斯（Charles Sanders Peirce, 1839-1914）&quot;">​</a></h3><p>皮尔斯是实用主义的创始人，但他的思想长期被忽视，直到威廉·詹姆斯重新发现并传播。</p><p><strong>核心命题：概念的意义在于可想到的实际效果</strong></p><blockquote><p>&quot;考虑你的概念对象可能包含什么样的可想到的实践效果，那么你对这些效果的概念就是你对这个对象的全部概念。&quot;</p></blockquote><p><strong>皮尔斯的意义论示例：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问：&quot;面包&quot;这个词的意义是什么？</span></span>
<span class="line"><span>旧答案：面包是一种食物。</span></span>
<span class="line"><span>皮尔斯的答案：</span></span>
<span class="line"><span>  - 面包可以吃 → 带来营养效果</span></span>
<span class="line"><span>  - 面包可以买 → 带来交换效果</span></span>
<span class="line"><span>  - 面包可以分享 → 带来社交效果</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>  这些实际效果的总和 = &quot;面包&quot;这个词的全部意义</span></span></code></pre></div><p><strong>对&quot;真理&quot;的颠覆：</strong></p><ul><li>传统：真理是客观存在的，等待被发现</li><li>皮尔斯：真理是思想最终会达到的共同观点——&quot;研究的终点&quot;</li></ul><hr><h2 id="二、威廉·詹姆斯-实用主义的大众化" tabindex="-1">二、威廉·詹姆斯：实用主义的大众化 <a class="header-anchor" href="#二、威廉·詹姆斯-实用主义的大众化" aria-label="Permalink to &quot;二、威廉·詹姆斯：实用主义的大众化&quot;">​</a></h2><h3 id="_2-1-威廉·詹姆斯-william-james-1842-1910" tabindex="-1">2.1 威廉·詹姆斯（William James, 1842-1910） <a class="header-anchor" href="#_2-1-威廉·詹姆斯-william-james-1842-1910" aria-label="Permalink to &quot;2.1 威廉·詹姆斯（William James, 1842-1910）&quot;">​</a></h3><p>詹姆斯将皮尔斯的抽象哲学转化为通俗易懂的思想运动，1907年出版《实用主义》，使实用主义成为美国主流思潮。</p><h3 id="_2-2-詹姆斯论真理" tabindex="-1">2.2 詹姆斯论真理 <a class="header-anchor" href="#_2-2-詹姆斯论真理" aria-label="Permalink to &quot;2.2 詹姆斯论真理&quot;">​</a></h3><p><strong>经典定义：真理是有用的事物</strong></p><blockquote><p>&quot;真理是对我们经验的有用处理方式。&quot;</p></blockquote><p><strong>詹姆斯的澄清：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是&quot;因为有用，所以是真的&quot;</span></span>
<span class="line"><span>而是&quot;真的，就是有用的&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有用 = 能让我们更好地适应环境</span></span>
<span class="line"><span>       能帮助我们解决问题</span></span>
<span class="line"><span>       能产生实际效果</span></span></code></pre></div><p><strong>真理与信仰：</strong></p><blockquote><p>实用主义对上帝存在问题的回答：&quot;上帝存在有没有实际区别？如果有，那这个问题对生活有实际意义；如果没有，那争论就毫无意义。&quot;</p></blockquote><p>这种态度使实用主义对宗教持开放但不狂热的态度。</p><h3 id="_2-3-詹姆斯论情感与理性" tabindex="-1">2.3 詹姆斯论情感与理性 <a class="header-anchor" href="#_2-3-詹姆斯论情感与理性" aria-label="Permalink to &quot;2.3 詹姆斯论情感与理性&quot;">​</a></h3><p><strong>实用主义的一大贡献：</strong> 承认情感在决策中的作用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统观点：理性决定，情感服从</span></span>
<span class="line"><span>实用主义：理性和情感都是适应工具</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 理性回答：&quot;哪个选项更合理？&quot;</span></span>
<span class="line"><span>- 情感回答：&quot;哪个选项让我感觉更好？&quot;</span></span>
<span class="line"><span>- 两者共同作用 → 最终决定</span></span></code></pre></div><hr><h2 id="三、约翰·杜威-实用主义的集大成者" tabindex="-1">三、约翰·杜威：实用主义的集大成者 <a class="header-anchor" href="#三、约翰·杜威-实用主义的集大成者" aria-label="Permalink to &quot;三、约翰·杜威：实用主义的集大成者&quot;">​</a></h2><h3 id="_3-1-约翰·杜威-john-dewey-1859-1952" tabindex="-1">3.1 约翰·杜威（John Dewey, 1859-1952） <a class="header-anchor" href="#_3-1-约翰·杜威-john-dewey-1859-1952" aria-label="Permalink to &quot;3.1 约翰·杜威（John Dewey, 1859-1952）&quot;">​</a></h3><p>杜威是实用主义哲学的巅峰人物，他将实用主义发展为完整的**工具主义（Instrumentalism）**体系，影响了教育、政治、文化各个领域。</p><p><strong>杜威的中国行：</strong></p><ul><li>1919年访问中国，在中国各地演讲</li><li>亲眼见证五四运动</li><li>胡适、陶行知等都是杜威的学生</li></ul><h3 id="_3-2-工具主义-思想是行动的工具" tabindex="-1">3.2 工具主义：思想是行动的工具 <a class="header-anchor" href="#_3-2-工具主义-思想是行动的工具" aria-label="Permalink to &quot;3.2 工具主义：思想是行动的工具&quot;">​</a></h3><p><strong>核心思想：</strong></p><blockquote><p>概念、理论、信念——它们不是&quot;镜子&quot;反映世界，而是&quot;工具&quot;改造世界。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>旧观点：思想 = 对世界的准确描述（像照片）</span></span>
<span class="line"><span>杜威观点：思想 = 行动的工具（像锤子）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检验工具的标准：好用不好用</span></span>
<span class="line"><span>检验思想的标准：效果怎么样</span></span></code></pre></div><p><strong>工具主义的方法论：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>遇到问题</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>提出假设（可能的解决方案）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>行动实验（测试效果）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>根据结果修正假设</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>继续实验...</span></span></code></pre></div><blockquote><p>这与毛泽东《实践论》高度一致！参见：<a href="/zhishiku-reading/topics/mao-zedong/mao-philosophy-practice-contradiction.html">毛泽东哲学：实践论</a></p></blockquote><h3 id="_3-3-民主作为生活方式" tabindex="-1">3.3 民主作为生活方式 <a class="header-anchor" href="#_3-3-民主作为生活方式" aria-label="Permalink to &quot;3.3 民主作为生活方式&quot;">​</a></h3><p><strong>杜威对民主的理解：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统理解：民主 = 选举 + 投票 + 多党制</span></span>
<span class="line"><span>杜威的理解：民主 = 共同体成员的平等参与 + 自由协商 + 共同成长</span></span>
<span class="line"><span></span></span>
<span class="line"><span>民主不仅是政治制度</span></span>
<span class="line"><span>更是一种生活方式——</span></span>
<span class="line"><span>每个个体都能充分发展</span></span>
<span class="line"><span>社区通过协商解决问题</span></span>
<span class="line"><span>知识和智慧通过对话产生</span></span></code></pre></div><p><strong>杜威论教育：</strong></p><blockquote><p>&quot;教育不是为生活做准备，教育就是生活本身。&quot;</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统教育：教师讲，学生听（知识灌输）</span></span>
<span class="line"><span>杜威的教育：做中学（Learning by Doing）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>学生不是容器等待填充</span></span>
<span class="line"><span>而是主动探索、实验、成长的生命体</span></span></code></pre></div><h3 id="_3-4-杜威思想的现实意义" tabindex="-1">3.4 杜威思想的现实意义 <a class="header-anchor" href="#_3-4-杜威思想的现实意义" aria-label="Permalink to &quot;3.4 杜威思想的现实意义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>领域</th><th>杜威的应用</th></tr></thead><tbody><tr><td><strong>教育</strong></td><td>做中学，探究式学习</td></tr><tr><td><strong>民主</strong></td><td>协商民主，公民参与</td></tr><tr><td><strong>科学</strong></td><td>科学是解决问题的工具，不是绝对真理的来源</td></tr><tr><td><strong>道德</strong></td><td>道德准则是应对情境的工具，需要灵活运用</td></tr></tbody></table><hr><h2 id="四、实用主义在中国-胡适与毛泽东" tabindex="-1">四、实用主义在中国：胡适与毛泽东 <a class="header-anchor" href="#四、实用主义在中国-胡适与毛泽东" aria-label="Permalink to &quot;四、实用主义在中国：胡适与毛泽东&quot;">​</a></h2><h3 id="_4-1-胡适-实用主义的中国传播者" tabindex="-1">4.1 胡适：实用主义的中国传播者 <a class="header-anchor" href="#_4-1-胡适-实用主义的中国传播者" aria-label="Permalink to &quot;4.1 胡适：实用主义的中国传播者&quot;">​</a></h3><p><strong>胡适</strong>（1891-1962）是杜威的学生，也是实用主义在中国的最主要传播者。</p><p><strong>胡适的实用主义立场：</strong></p><blockquote><p>&quot;实用主义只是要人把人生活泼泼的，要人实地的经验一切，别给玄学家空中楼阁。&quot;</p></blockquote><p><strong>胡适的&quot;大胆假设，小心求证&quot;：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实用主义方法论的中国化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步（大胆假设）：</span></span>
<span class="line"><span>  提出可能的解释</span></span>
<span class="line"><span>  不怕错，只怕不试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步（小心求证）：</span></span>
<span class="line"><span>  收集证据</span></span>
<span class="line"><span>  用实际效果检验假设</span></span></code></pre></div><p><strong>胡适的&quot;少谈些主义，多研究些问题&quot;：</strong></p><blockquote><p>不是反对理想，而是强调从具体问题入手。宏大理论要用到具体问题的解决上才有意义。</p></blockquote><h3 id="_4-2-毛泽东实践论与实用主义的呼应" tabindex="-1">4.2 毛泽东实践论与实用主义的呼应 <a class="header-anchor" href="#_4-2-毛泽东实践论与实用主义的呼应" aria-label="Permalink to &quot;4.2 毛泽东实践论与实用主义的呼应&quot;">​</a></h3><p><strong>关键发现：毛泽东的《实践论》与杜威的实用主义有深刻联系</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>杜威（实用主义）</th><th>毛泽东（实践论）</th></tr></thead><tbody><tr><td><strong>认识的起点</strong></td><td>遇到问题情境</td><td>实践 → 感性认识</td></tr><tr><td><strong>认识的过程</strong></td><td>提出假设 → 实验验证</td><td>感性认识 → 理性认识</td></tr><tr><td><strong>真理的标准</strong></td><td>实际效果</td><td>实践检验</td></tr><tr><td><strong>认识的循环</strong></td><td>持续探究，永不停止</td><td>实践-认识-再实践，循环往复</td></tr></tbody></table><p><strong>李泽厚的分析：</strong> 中国现代哲学家李泽厚指出，毛泽东《实践论》直接继承了杜威的实用主义方法论，并与中国革命实践结合。</p><p><strong>跨文本交叉引用：</strong></p><blockquote><p>毛泽东《实践论》原文：&quot;通过实践而发现真理，又通过实践而证实真理和发展真理。&quot;</p><p>杜威原文：&quot;思想的唯一意义在于它指引行动的效果。&quot;</p><p>两者本质上是同一方法论在不同语境下的表述。参见：<a href="/zhishiku-reading/topics/mao-zedong/mao-philosophy-practice-contradiction.html">毛泽东哲学：实践论与矛盾论</a></p></blockquote><hr><h2 id="五、实用主义的核心方法论" tabindex="-1">五、实用主义的核心方法论 <a class="header-anchor" href="#五、实用主义的核心方法论" aria-label="Permalink to &quot;五、实用主义的核心方法论&quot;">​</a></h2><h3 id="_5-1-解决问题的工作流" tabindex="-1">5.1 解决问题的工作流 <a class="header-anchor" href="#_5-1-解决问题的工作流" aria-label="Permalink to &quot;5.1 解决问题的工作流&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实用主义方法论（五步法）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 感到困难/问题</span></span>
<span class="line"><span>   ↓ 识别问题情境</span></span>
<span class="line"><span>2. 界定问题（是什么问题？边界在哪？）</span></span>
<span class="line"><span>   ↓ 准确描述</span></span>
<span class="line"><span>3. 提出可能的解决方案（假设）</span></span>
<span class="line"><span>   ↓ 开放头脑</span></span>
<span class="line"><span>4. 推理每个方案的可能后果</span></span>
<span class="line"><span>   ↓ 逻辑推演</span></span>
<span class="line"><span>5. 验证/选择最好的方案</span></span>
<span class="line"><span>   ↓ 实践检验</span></span></code></pre></div><h3 id="_5-2-效果导向的决策框架" tabindex="-1">5.2 效果导向的决策框架 <a class="header-anchor" href="#_5-2-效果导向的决策框架" aria-label="Permalink to &quot;5.2 效果导向的决策框架&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>决策标准 = 效果评估</span></span>
<span class="line"><span></span></span>
<span class="line"><span>行动前问：</span></span>
<span class="line"><span>1. 这个行动会产生什么效果？</span></span>
<span class="line"><span>2. 这些效果对我们有利吗？</span></span>
<span class="line"><span>3. 有没有更好的替代方案？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>行动后问：</span></span>
<span class="line"><span>1. 产生了预期效果吗？</span></span>
<span class="line"><span>2. 有没有意外后果？</span></span>
<span class="line"><span>3. 下次如何改进？</span></span></code></pre></div><hr><h2 id="六、实用主义的价值与局限" tabindex="-1">六、实用主义的价值与局限 <a class="header-anchor" href="#六、实用主义的价值与局限" aria-label="Permalink to &quot;六、实用主义的价值与局限&quot;">​</a></h2><h3 id="_6-1-实用主义的贡献" tabindex="-1">6.1 实用主义的贡献 <a class="header-anchor" href="#_6-1-实用主义的贡献" aria-label="Permalink to &quot;6.1 实用主义的贡献&quot;">​</a></h3><table tabindex="0"><thead><tr><th>贡献</th><th>说明</th></tr></thead><tbody><tr><td><strong>反教条主义</strong></td><td>不迷信任何理论，效果才是检验标准</td></tr><tr><td><strong>强调行动</strong></td><td>思想的价值在于指导行动</td></tr><tr><td><strong>承认不确定性</strong></td><td>知识是开放的、可以修正的</td></tr><tr><td><strong>重视效果</strong></td><td>避免空谈，注重实际改变</td></tr></tbody></table><h3 id="_6-2-实用主义的批评" tabindex="-1">6.2 实用主义的批评 <a class="header-anchor" href="#_6-2-实用主义的批评" aria-label="Permalink to &quot;6.2 实用主义的批评&quot;">​</a></h3><table tabindex="0"><thead><tr><th>批评</th><th>回应</th></tr></thead><tbody><tr><td><strong>&quot;只顾眼前效果&quot;</strong></td><td>好的效果也是长期的，鼠目寸光不是实用主义</td></tr><tr><td><strong>&quot;为成功者辩护&quot;</strong></td><td>实用主义关注所有人的实际福祉</td></tr><tr><td><strong>&quot;相对主义&quot;</strong></td><td>不否认客观真理，只是强调真理需要实践验证</td></tr><tr><td><strong>&quot;工具理性&quot;</strong></td><td>实用主义也关注民主、艺术、道德等价值</td></tr></tbody></table><hr><h2 id="七、实用主义的现实应用" tabindex="-1">七、实用主义的现实应用 <a class="header-anchor" href="#七、实用主义的现实应用" aria-label="Permalink to &quot;七、实用主义的现实应用&quot;">​</a></h2><h3 id="_7-1-工作中的应用" tabindex="-1">7.1 工作中的应用 <a class="header-anchor" href="#_7-1-工作中的应用" aria-label="Permalink to &quot;7.1 工作中的应用&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目管理：</span></span>
<span class="line"><span>- 不是理论最优方案，而是效果最好的方案</span></span>
<span class="line"><span>- 试点验证，再全面推广</span></span>
<span class="line"><span>- 根据效果持续调整</span></span>
<span class="line"><span></span></span>
<span class="line"><span>领导力：</span></span>
<span class="line"><span>- 关注决策的实际效果，不为面子买单</span></span>
<span class="line"><span>- 鼓励实验，接受失败，从失败中学习</span></span></code></pre></div><h3 id="_7-2-民主协商中的应用" tabindex="-1">7.2 民主协商中的应用 <a class="header-anchor" href="#_7-2-民主协商中的应用" aria-label="Permalink to &quot;7.2 民主协商中的应用&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>政策制定：</span></span>
<span class="line"><span>- 不是一方赢另一方输，而是协商出最优解</span></span>
<span class="line"><span>- 充分讨论，预判各方案的效果</span></span>
<span class="line"><span>- 政策需要不断根据效果调整</span></span></code></pre></div><h3 id="_7-3-个人成长中的应用" tabindex="-1">7.3 个人成长中的应用 <a class="header-anchor" href="#_7-3-个人成长中的应用" aria-label="Permalink to &quot;7.3 个人成长中的应用&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>学习：</span></span>
<span class="line"><span>- 不是学&quot;有用的知识&quot;，而是边做边学</span></span>
<span class="line"><span>- 知识需要在实践中验证和深化</span></span>
<span class="line"><span></span></span>
<span class="line"><span>决策：</span></span>
<span class="line"><span>- 不追求完美方案，而是选择当下最优</span></span>
<span class="line"><span>- 决策后根据效果调整</span></span></code></pre></div><hr><h2 id="八、实用主义-vs-其他哲学流派" tabindex="-1">八、实用主义 vs 其他哲学流派 <a class="header-anchor" href="#八、实用主义-vs-其他哲学流派" aria-label="Permalink to &quot;八、实用主义 vs 其他哲学流派&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实用主义 vs 理性主义：</span></span>
<span class="line"><span>  理性主义：先想清楚再做</span></span>
<span class="line"><span>  实用主义：边做边想，效果导向</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实用主义 vs 经验主义：</span></span>
<span class="line"><span>  经验主义：知识来自观察</span></span>
<span class="line"><span>  实用主义：知识来自行动验证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实用主义 vs 康德：</span></span>
<span class="line"><span>  康德：道德法则先于行动</span></span>
<span class="line"><span>  实用主义：道德准则是应对情境的工具</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实用主义 vs 功利主义：</span></span>
<span class="line"><span>  功利主义：最大多数人的最大幸福是目标</span></span>
<span class="line"><span>  实用主义：效果是检验标准，幸福是其中一种效果</span></span></code></pre></div><hr><p><em>整理日期：2026-06-17</em><em>建议交叉阅读：</em></p><ul><li><em>毛泽东哲学《实践论》（实用主义方法论的中国化）</em></li><li><em>毛泽东哲学《矛盾论》（辩证法与实用主义的结合）</em></li><li><em>认识论与科学哲学（波普尔的证伪主义与实用主义的对话）</em></li><li><em>中国传统哲学（知行合一与实用主义的相通之处）</em></li></ul>`,90)])])}const g=s(e,[["render",l]]);export{u as __pageData,g as default};
